css:
.print-format-container {
    font-family: Arial, sans-serif;
    font-size: 12px;
    line-height: 1.5;
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
}
.row {
    display: flex;
    flex-wrap: wrap;
}

.col-70 { flex: 0 0 70%; max-width: 70%; }
.col-30 { flex: 0 0 30%; max-width: 30%; text-align: right; }
.col-6 { flex: 0 0 50%; max-width: 50%; }
.col-12 { flex: 0 0 100%; max-width: 100%; }

.company-logo img {
    max-width: 150px;
    height: auto;
}

.section-details div, .section-incapacity div {
    margin-bottom: 5px;
}
